CREATE TABLE IF NOT EXISTS system_agent_teams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_key TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',config JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_agent_team_members (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID NOT NULL,agent_id UUID NOT NULL,role TEXT NOT NULL DEFAULT 'member',status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_agent_team_tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',assigned_agent_id UUID,priority INTEGER NOT NULL DEFAULT 50,context JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_agent_handoffs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID,from_agent_id UUID,to_agent_id UUID,task_id UUID,status TEXT NOT NULL DEFAULT 'pending',context JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_agent_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID,from_agent_id UUID,to_agent_id UUID,message_type TEXT NOT NULL DEFAULT 'task',content JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_agent_team_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID,event_type TEXT NOT NULL,detail JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_agent_team_user ON system_agent_teams(user_id,status);
CREATE INDEX IF NOT EXISTS idx_agent_team_member ON system_agent_team_members(user_id,team_id,status);
CREATE INDEX IF NOT EXISTS idx_agent_team_task ON system_agent_team_tasks(user_id,team_id,status);
CREATE INDEX IF NOT EXISTS idx_agent_message_team ON system_agent_messages(user_id,team_id,created_at DESC);